import java.io.*;
import java.util.*;

public class Main {

    public static void main(String[] args) throws Exception {
        Main app = new Main();
        app.start();
    }

    private void start() throws Exception {
        InputHandler in = new InputHandler(System.in);
        OutputHandler out = new OutputHandler(System.out);
        Problem task = new Problem();
        task.run(1, in, out);
        out.flush();
    }

    static class Problem {
        private static final long MOD = 998244353L;
        private long[] factorial;
        private long[] invFactorial;

        private long fastPow(long base, long exp) {
            long result = 1L;
            base %= MOD;
            while (exp > 0) {
                if ((exp & 1) == 1) result = (result * base) % MOD;
                base = (base * base) % MOD;
                exp >>>= 1;
            }
            return result;
        }

        public void run(int testId, InputHandler in, OutputHandler out) {
            int limit = 200001;
            factorial = new long[limit];
            invFactorial = new long[limit];
            factorial[0] = invFactorial[0] = 1L;
            for (int i = 1; i < limit; i++) {
                factorial[i] = factorial[i - 1] * i % MOD;
                invFactorial[i] = invFactorial[i - 1] * fastPow(i, MOD - 2) % MOD;
            }

            int n = in.nextInt();
            long k = in.nextLong();

            if (k >= n) {
                out.println(0);
                return;
            }
            if (k == 0) {
                out.println(factorial[n]);
                return;
            }

            int m = n - (int)k;
            long total = 0L;
            for (int i = 0; i <= m; i++) {
                long contribution = binomial(m, i) * fastPow(m - i, n) % MOD;
                total = ((i & 1) == 0) ? (total + contribution) % MOD : (total - contribution + MOD) % MOD;
            }

            long answer = 2L * factorial[n] % MOD;
            answer = answer * invFactorial[n - m] % MOD;
            answer = answer * total % MOD;
            answer = answer * invFactorial[m] % MOD;
            out.println(answer);
        }

        private long binomial(int n, int r) {
            return factorial[n] * invFactorial[r] % MOD * invFactorial[n - r] % MOD;
        }
    }

    static class InputHandler {
        private BufferedReader reader;
        private String[] buffer;
        private int pos;

        public InputHandler(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            buffer = new String[0];
            pos = 0;
        }

        private void loadMore() throws IOException {
            String line = reader.readLine();
            if (line == null) throw new EOFException();
            buffer = line.split("\\s+");
            pos = 0;
        }

        public String next() throws IOException {
            if (pos >= buffer.length) loadMore();
            return buffer[pos++];
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }

    static class OutputHandler {
        private PrintWriter writer;

        public OutputHandler(OutputStream stream) {
            writer = new PrintWriter(stream, true);
        }

        public void println(long value) {
            writer.println(value);
        }

        public void flush() {
            writer.flush();
        }
    }
}
